+	patch("src/store.test.ts", [
+		"@@ -1 +1,2 @@",
+		" it('loads')",
+		"+it('caches')",
+	]),
+	patch("bun.lock", ["@@ -1 +1 @@", "-a", "+b"]),
+	patch("src/fmt.ts", [
+		"@@ -1,2 +1,2 @@",
+		"-\tif (a) {",
