+		const text = lines[index] ?? "";
+		if (text.trim() === "" || indentOf(text) >= target || CLOSER.test(text))
+			continue;
+		if (isDefinition(text)) return index + 1;
+		fallback ??= index + 1;
+	}
+	return fallback;
